head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setCellDataType]<br/>Body Cell 정보를 사용하여 특정 Body Cell 의 dataType 속성을 설정합니다.",
    "validation" : [
        "Column 의 inputType 이 'custom' 이고, Cell 의 inputType 속성값이 'text','textarea','input','secret' 인 경우에만 동작합니다.",
        "rowIndex(필수) 파라미터로 dataType 속성을 설정할 Body Cell 의 Row 인덱스를 설정할 수 있어야 합니다.",
        "rowIndex(필수) 파라미터의 Row 인덱스는 0 부터 시작하며 GridView 에 표시된 Row 를 기준으로 인덱스가 설정됩니다.",
        "rowIndex(필수) 파라미터는 Body 가 MultiLine 일때 각 Line 의 Row 인덱스값은 같습니다.",
        "columnInfo(필수) 파라미터로 dataType 속성을 설정할 Body Cell 의 Column 인덱스를 설정할 수 있어야 합니다.",
        "columnInfo(필수) 파라미터의 Column 인덱스는 0 부터 시작하며 숨겨진 Column 도 포함하여 인덱스가 설정됩니다.",
        "columnInfo(필수) 파라미터는 Row 가 MultiLine 이어도 모든 Column 은 고유의 인덱스값을 갖습니다.",
        "dataType(필수) 파라미터로 'number' 를 설정하여 Cell 의 dataType 속성을 변경할 수 있어야 합니다.",
        "dataType(필수) 파라미터로 'float' 를 설정하여 Cell 의 dataType 속성을 변경할 수 있어야 합니다.",
        "dataType(필수) 파라미터로 'bigDecimal' 를 설정하여 Cell 의 dataType 속성을 변경할 수 있어야 합니다.",
        "dataType(필수) 파라미터로 'text' 를 설정하여 Cell 의 dataType 속성을 변경할 수 있어야 합니다.",
        "dataType(필수) 파라미터로 'date' 를 설정하여 Cell 의 dataType 속성을 변경할 수 있어야 합니다.",
        "dataType(필수) 파라미터로 'time' 를 설정하여 Cell 의 dataType 속성을 변경할 수 있어야 합니다.",
        "Body Column 의 dataType 을 변경하려면 setDataType() 메소드를 사용해야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] 인덱스 0(col1) = inputType=custom + typeGetter 로 Cell inputType=text -> setCellDataType 동작. 인덱스 1(col2)은 숨김 처리(숨김 Column 도 인덱스 포함). 인덱스 2(col3) = 일반 inputType=text (custom 아님) -> 전제 미충족(미동작). 인덱스 3(col4) = inputType=custom + typeGetter 로 Cell inputType=spinner (4종 외) -> 전제 미충족(미동작)\n[절차] rowIndex + columnInfo(인덱스) + dataType 선택 후 setCellDataType 실행\n[확인] 전제 충족 셀(인덱스 0)만 표시값이 dataType 에 맞게 변경되고, 전제 미충족 셀(인덱스 2/3)은 변경 전/후 표시값이 동일(미동작)"', '', 'label1');

    // dataList 생성 (기본 col1~col4, dataType=text) + 데이터 바인딩
    //  값 1234567.89 : number=1234568 / float=1234567.89 / text=1234567.89 형태로 Cell dataType 변경 시 표시 차이가 드러남
    let strNameSpace = $c.gcm.getNameSpace();
    $c.gcm.createBasicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON([
        { "col1": "1234567.89", "col2": "H0", "col3": "1234567.89", "col4": "12" },
        { "col1": "2345678.91", "col2": "H1", "col3": "2345678.91", "col4": "23" },
        { "col1": "3456789.12", "col2": "H2", "col3": "3456789.12", "col4": "34" },
        { "col1": "4567890.23", "col2": "H3", "col3": "4567890.23", "col4": "45" }
    ]);

    // target 생성
    //  col1 : inputType=custom + typeGetter(Cell inputType=text)  -> setCellDataType 동작 대상
    //  col2 : inputType=text (숨김 처리)                          -> 숨김 Column 인덱스 포함 검증용
    //  col3 : inputType=text (custom 아님)                        -> 전제 미충족(미동작) 대조
    //  col4 : inputType=custom + typeGetter(Cell inputType=spinner) -> Cell inputType 4종 외(미동작) 대조
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' checkAllType="false" dataList="data:dlt_bind" id="" style="width:720px;height:200px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="180" inputType="text" id="hcol1" value="col1 (custom->text)"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="hcol2" value="col2 (숨김)"></w2:column>';
    strTarget += '<w2:column width="180" inputType="text" id="hcol3" value="col3 (일반 text)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol4" value="col4 (custom->spinner)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="180" inputType="custom" dataType="text" id="col1" dataList="col1" typeGetter="scwin.target1_textTypeGetter"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" dataType="text" id="col2" dataList="col2"></w2:column>';
    strTarget += '<w2:column width="180" inputType="text" dataType="text" id="col3" dataList="col3"></w2:column>';
    strTarget += '<w2:column width="*" inputType="custom" dataType="text" id="col4" dataList="col4" typeGetter="scwin.target1_spinnerTypeGetter"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);

    // 숨겨진 Column 포함 인덱스 검증용으로 두번째 컬럼(인덱스 1, col2) 숨김
    target1.setColumnVisible(1, false);
}



// col1(custom) : 각 Cell 을 inputType=text 로 구성 -> setCellDataType 동작 가능
scwin.target1_textTypeGetter = function (info) {
    return {
        id: 'cell_text_' + info.rowIndex + '_' + info.colIndex,
        inputType: 'text',
        options: { textAlign: 'right' }
    };
};



// col4(custom) : 각 Cell 을 inputType=spinner(4종 외) 로 구성 -> setCellDataType 미동작 대조
scwin.target1_spinnerTypeGetter = function (info) {
    return {
        id: 'cell_spinner_' + info.rowIndex + '_' + info.colIndex,
        inputType: 'spinner',
        options: {}
    };
};



scwin.btn_setCellDataType_onclick = function () {
    let rowIndex = Number(par_rowIndex.getValue());
    let columnInfo = Number(par_columnInfo.getValue());
    let dataType = par_dataType.getValue();

    // 변경 전 표시값 (dataType 변경은 Cell 의 표시값을 새 포맷으로 재처리하므로 표시값 변화로 확인)
    let colID = scwin.target1.getColumnID(columnInfo);
    let beforeDisplay = scwin.target1.getCellDisplayData(rowIndex, colID);

    scwin.target1.setCellDataType(rowIndex, columnInfo, dataType);

    let afterDisplay = scwin.target1.getCellDisplayData(rowIndex, colID);

    let changed = (beforeDisplay !== afterDisplay);
    wf_body_bottom.getObj("scwin").setReturnValue(
        "setCellDataType(" + rowIndex + ", " + columnInfo + ", '" + dataType + "') | 변경 전 표시값 : '" + beforeDisplay + "' -> 변경 후 표시값 : '" + afterDisplay + "' | 표시값 변경됨 : " + changed);
}
